import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"The Handl type system","description":"","frontmatter":{},"headers":[],"relativePath":"learn/index.md","filePath":"learn/index.md"}`),a={name:`learn/index.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="the-handl-type-system" tabindex="-1">The Handl type system <a class="header-anchor" href="#the-handl-type-system" aria-label="Permalink to “The Handl type system”">​</a></h1><p>One calculus for programs, proofs, types, effects, and modes, where equality, transport, and univalence all <em>compute</em>, and the typechecker itself is a program in the same language it checks.</p><p>Everything on this page is ordinary Handl: types are values, proofs are witnesses, judgments are data. There is no separate type-theoretic subsystem. Dependent structure, equality, effects, and modes are all cells in the same arrow calculus.</p><h2 id="core-one-binder-one-arrow" tabindex="-1">Core: one binder, one arrow <a class="header-anchor" href="#core-one-binder-one-arrow" aria-label="Permalink to “Core: one binder, one arrow”">​</a></h2><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>x := 42</span></span>
<span class="line"><span>id : Nat ~&gt; Nat := n ~&gt; n</span></span>
<span class="line"><span>pair := [1, &quot;two&quot;]</span></span>
<span class="line"><span>rec := { name: &quot;luis&quot;, age: 30 }</span></span></code></pre></div><p><code>:=</code> is the only binder. <code>~&gt;</code> is the only arrow: terms and types share it, and data declarations are <code>new</code> expressions. Module forms such as <code>export</code> control visibility only; they play no role in typing.</p><h2 id="inductive-families" tabindex="-1">Inductive families <a class="header-anchor" href="#inductive-families" aria-label="Permalink to “Inductive families”">​</a></h2><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Nat := new Inductive {</span></span>
<span class="line"><span>  zero : Nat,</span></span>
<span class="line"><span>  succ : (pred : Nat) ~&gt; Nat</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Vec&lt;n : Nat, a : Type&gt; := new Inductive {</span></span>
<span class="line"><span>  vnil  : Vec(0, a),</span></span>
<span class="line"><span>  vcons : (x : a, xs : Vec(n, a)) ~&gt; Vec(n + 1, a)</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>v1 : Vec&lt;2, Bool&gt; := vcons(true, vcons(false, vnil))</span></span></code></pre></div><p><code>&lt;n : Nat, a : Type&gt;</code> declares indexed families. <code>Vec(2, Bool)</code> is a <code>family_app</code> whose indices <strong>compute</strong>: <code>Vec&lt;1+1&gt;</code> is <code>Vec&lt;2-0&gt;</code> is <code>Vec&lt;2*1&gt;</code>, and all check against the same value.</p><h2 id="inductives-as-data" tabindex="-1">Inductives as data <a class="header-anchor" href="#inductives-as-data" aria-label="Permalink to “Inductives as data”">​</a></h2><p>An inductive specification is itself a value: an <code>inductive.spec</code> record of constructor signatures as owned type expressions. Specs can be computed, composed, inspected, and passed to generic eliminators; the same spec drives <code>match</code> refinement and <code>F.rec</code>-style folds. Positivity is a checker judgment over the spec value, not a parse-time native.</p><h2 id="dependent-types-π-and-σ" tabindex="-1">Dependent types: Π and Σ <a class="header-anchor" href="#dependent-types-π-and-σ" aria-label="Permalink to “Dependent types: Π and Σ”">​</a></h2><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>-- Π: a typed-binder arrow in type position</span></span>
<span class="line"><span>idp : (x : Nat) ~&gt; Nat := x ~&gt; x</span></span>
<span class="line"><span>curried : (x : Nat, y : Bool) ~&gt; Nat := x ~&gt; y ~&gt; x</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- Σ: a typed-binder list with no arrow is a dependent pair</span></span>
<span class="line"><span>one_vec : (m : Nat, v : Vec(m, Bool)) := [succ(zero), vcons(true, vnil)]</span></span>
<span class="line"><span>prod : (x : Bool, y : String) := [true, &quot;hi&quot;]</span></span></code></pre></div><h2 id="dependent-elimination-match" tabindex="-1">Dependent elimination: match <a class="header-anchor" href="#dependent-elimination-match" aria-label="Permalink to “Dependent elimination: match”">​</a></h2><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>vtail&lt;n, a&gt; : Vec&lt;n + 1, a&gt; ~&gt; Vec&lt;n, a&gt; :=</span></span>
<span class="line"><span>  v ~&gt; match v { vcons(x, xs): xs }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>vhead&lt;n, a&gt; : Vec&lt;succ n, a&gt; ~&gt; a :=</span></span>
<span class="line"><span>  v ~&gt; match v { vcons(x, xs): x }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>is_nil : Vec&lt;n, a&gt; ~&gt; Bool :=</span></span>
<span class="line"><span>  v ~&gt; match v { vnil: true, vcons(x, xs): false }</span></span></code></pre></div><p>Under <code>vcons</code>, the checker refines <code>n ≡ ?k+1</code>, binds <code>xs : Vec&lt;?k, a&gt;</code>, and records a proof-relevant <code>eq_n</code> path witness. Impossible arms are decided: <code>vnil: absurd</code> checks iff the branch&#39;s index equations are unsatisfiable.</p><h2 id="eliminators-and-motives" tabindex="-1">Eliminators and motives <a class="header-anchor" href="#eliminators-and-motives" aria-label="Permalink to “Eliminators and motives”">​</a></h2><p>Family eliminators are visible to the checker:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>len_via_rec : Nat := Vec.rec(null, zero, step)(2, Bool, v1)</span></span></code></pre></div><p>And motives can be stated explicitly:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>id_vec : (n : Nat) ~&gt; (v : Vec(n + 0, Bool)) ~&gt; Vec(n + 0, Bool) :=</span></span>
<span class="line"><span>  n ~&gt; v ~&gt; match v return (i, w) ~&gt; Vec(i, Bool) with {</span></span>
<span class="line"><span>    vnil:    J eq_n, (i2, w2) ~&gt; Vec(i2, Bool), v,</span></span>
<span class="line"><span>    vcons(x, xs): eq_n # v</span></span>
<span class="line"><span>  }</span></span></code></pre></div><h2 id="equality-paths-are-data" tabindex="-1">Equality: paths are data <a class="header-anchor" href="#equality-paths-are-data" aria-label="Permalink to “Equality: paths are data”">​</a></h2><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>p : Path(1, 1) := refl</span></span>
<span class="line"><span>moved : Nat := p # zero</span></span>
<span class="line"><span>transported : Nat := transport(p, zero)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tt : Path(Nat, zero, succ(succ(zero))) := trans pt, qt</span></span>
<span class="line"><span>st := symm(tt)</span></span>
<span class="line"><span>jv : Vec&lt;2, Bool&gt; := J p22, (i, w) ~&gt; Vec(i, Bool), v2</span></span></code></pre></div><p>Unification itself consumes in-scope paths: <code>P[frm]</code> against <code>P[to]</code> succeeds when a <code>Path</code> bound in the environment justifies the rewrite. Equality is weak and proof-relevant, never erased: transport along a path <em>is</em> substitution.</p><h2 id="cubical-structure" tabindex="-1">Cubical structure <a class="header-anchor" href="#cubical-structure" aria-label="Permalink to “Cubical structure”">​</a></h2><p>Paths are not an axiomatized identity type; they are terms over an interval <code>I</code>, and the Kan operations that make them compute are ordinary primitives:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>cp : Path(Bool, true, true) := i ~&gt; true</span></span>
<span class="line"><span>t1 := transp Pi(I, i ~&gt; Bool), i0, fF, true</span></span>
<span class="line"><span>h1 : Bool := hcomp Bool, i0, fF, true, false</span></span>
<span class="line"><span>y : unglue(Glue(Bool, fF, Pi(I, i ~&gt; Bool))) := true</span></span>
<span class="line"><span>pfB : isFibrant(Bool) := fibrant Bool</span></span></code></pre></div><p><code>transp</code> is transport in a type family along a dimension, partial on a face; <code>hcomp</code> is homogeneous composition over a single type; <code>Glue</code> and <code>unglue</code> glue types along equivalences; <code>fibrant</code> is the fibrancy predicate the Kan structure is stated over.</p><h2 id="univalence-computes" tabindex="-1">Univalence computes <a class="header-anchor" href="#univalence-computes" aria-label="Permalink to “Univalence computes”">​</a></h2><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>eBN : Equiv(Bool, Nat) := { to: x ~&gt; zero, fro: y ~&gt; true }</span></span>
<span class="line"><span>tv : Nat := ua(eBN) # true        -- transport applies \`to\` and reduces</span></span>
<span class="line"><span>tb : Bool := symm(ua(eBN)) # zero</span></span></code></pre></div><p><code>ua(e)</code> mints a path over the interval carrying the recorded equivalence; transport along it applies the equivalence&#39;s functions. Univalence is a value, not an axiom.</p><h2 id="higher-categories-dimension-arrows" tabindex="-1">Higher categories: dimension arrows <a class="header-anchor" href="#higher-categories-dimension-arrows" aria-label="Permalink to “Higher categories: dimension arrows”">​</a></h2><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>comp_assoc := (a,b,c) ~&gt; ((a &gt;&gt;&gt;[2] b) &gt;&gt;&gt;[2] c)</span></span>
<span class="line"><span>                    ~&gt;[3]~&gt; (a &gt;&gt;&gt;[2] (b &gt;&gt;&gt;[2] c))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>interchange := (al,al2,be,be2) ~&gt;</span></span>
<span class="line"><span>  ((al =&gt;| al2) =&gt;&gt; (be =&gt;| be2)) ~&gt;[3]~&gt;</span></span>
<span class="line"><span>  ((al =&gt;&gt; be) =&gt;| (al2 =&gt;&gt; be2))</span></span></code></pre></div><p><code>~&gt;[n]</code> is the dimension-n arrow <code>Hom(n, ·, ·)</code>, consistent with <code>&gt;&gt;&gt;[k]</code> composing k-cells. <code>Path</code> itself is defined as a Sigma of 2-cells, their inverses, and coherence 3-cells; associativity, unitality, and interchange are <em>typechecked equations</em>, verified definitionally by normalization.</p><h2 id="effects-io-sig-codomain-formers" tabindex="-1">Effects: <code>IO&lt;sig&gt;</code> codomain formers <a class="header-anchor" href="#effects-io-sig-codomain-formers" aria-label="Permalink to “Effects: IO&lt;sig&gt; codomain formers”">​</a></h2><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>printLn : Str ~&gt; IO&lt;puts&gt;</span></span>
<span class="line"><span>both    : Str ~&gt; IO&lt;puts, fs&gt;</span></span>
<span class="line"><span>handled : Str ~&gt; IO&lt;puts: Unit, fs&gt; :=</span></span>
<span class="line"><span>  handle both with {puts: puts_handler}</span></span>
<span class="line"><span>widen_ok : Str ~&gt; IO&lt;puts, fs&gt; := s ~&gt; printLn(s)</span></span>
<span class="line"><span>perf    : IO&lt;{ puts: Str }&gt; := perform(puts, &quot;hi&quot;)</span></span></code></pre></div><p>Signature entries compute: a covered op takes its handler&#39;s return type; uncovered ops stay residual; effect widening is checked. Under the hood the signature is a <em>mode</em>: effects are one algebra on the same axis as grades and coeffects, and <code>IO&lt;sig&gt;</code> is the reified spelling of an ambient mode <code>{io: sig}</code> that <code>perform</code> extends and <code>handle</code> transforms.</p><h2 id="instances-and-evidence" tabindex="-1">Instances and evidence <a class="header-anchor" href="#instances-and-evidence" aria-label="Permalink to “Instances and evidence”">​</a></h2><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Eq := new Constraint(Type) {</span></span>
<span class="line"><span>  evidence : a ~&gt; a ~&gt; Bool</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>instance Eq(Nat) := { evidence: (x, y) ~&gt; x == y }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>eqv&lt;a, ev : Eq(a)&gt; : a ~&gt; a ~&gt; Bool :=</span></span>
<span class="line"><span>  x ~&gt; y ~&gt; ev.evidence(x, y)</span></span>
<span class="line"><span>nat_eq : Bool := eqv(zero)(zero)</span></span></code></pre></div><p><code>new</code> is the single declaration form for checker registries: <code>Inductive</code> (constructors and eliminators), <code>Algebra</code> (mode composition), <code>Constraint</code> (evidence dictionaries). An <code>instance</code> fills a registry slot; <code>ev : Eq(a)</code> binders are evidence-implicit, resolved by unification-driven dictionary search with declaration-time no-overlap coherence.</p><h2 id="modes-mtt-arrows" tabindex="-1">Modes: MTT arrows <a class="header-anchor" href="#modes-mtt-arrows" aria-label="Permalink to “Modes: MTT arrows”">​</a></h2><p>Modes unify grades, coeffects, and effects onto one axis. A mode is an arbitrary Handl data value; an algebra is an ordinary type, a record of <code>compose</code>/<code>unit</code>/<code>order</code> functions, declared once and selected by the mode&#39;s call head:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Cost := new Algebra(Nat) {</span></span>
<span class="line"><span>  compose: (a, b) ~&gt; a + b,</span></span>
<span class="line"><span>  unit:    0,</span></span>
<span class="line"><span>  order:   (a, b) ~&gt; a &lt;= b</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>f : A ~[Cost(2)]~&gt; B</span></span>
<span class="line"><span>g : B ~[Cost(5)]~&gt; C</span></span>
<span class="line"><span>h := g &gt;&gt;&gt; f        -- : A ~[Cost(7)]~&gt; C</span></span></code></pre></div><p><code>Cost(2)</code> composed with <code>Cost(5)</code> dispatches to the <code>Cost</code> instance&#39;s <code>compose</code>, so composition <em>computes</em> the mode. Subsumption is the algebra&#39;s <code>order</code>: an arrow usable at <code>Cost(3)</code> is accepted where <code>Cost(5)</code> is expected. Modes are data, so algebras are computable: transformers, products, and mode expressions like <code>Cost(3) + Session(p)</code> are ordinary functions returning algebra records.</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>mapM : (m : Mode) ~&gt; (f : A ~[m]~&gt; B) ~&gt; List(A) ~[m]~&gt; List(B)</span></span>
<span class="line"><span>costed := mapM(Cost(1), double)     -- mode polymorphism by substitution</span></span></code></pre></div><p><code>~&gt;[n]</code> remains the dimension arrow: globular structure, a different axis from modes.</p><h2 id="the-meta-layer-everything-is-data" tabindex="-1">The meta layer: everything is data <a class="header-anchor" href="#the-meta-layer-everything-is-data" aria-label="Permalink to “The meta layer: everything is data”">​</a></h2><p>The typechecker is itself a Handl program: types are <code>type.*</code> values, proofs are witnesses stored in the evaluation state, unification records its <code>via</code> paths, and algebras are records the checker interprets. Aliases are transparent expansions; <code>forall</code> is Pi-sugar; judgments are serializable, cacheable, parallelizable data.</p><p>Because types and terms share one evaluator, <strong>typechecking already runs your computations</strong>: normalizing <code>Vec(2, Bool)</code> evaluates indices, transport along <code>ua(e)</code> applies the equivalence, and <code>mode_compose</code> evaluates the governing algebra. The checker&#39;s normalization cache is a demand-driven partial evaluator whose results the runtime can inherit. Pure computations verified once at typecheck time are replayable at run time, and the purity boundary is itself typed: graded arrows mark exactly which computations may cross it.</p><hr><p><strong>One line:</strong> programs, proofs, types, effects, and modes are cells in one calculus, and equality, transport, univalence, and grading all <em>compute</em>.</p><p>The academic groundwork behind each layer is collected in the <a href="/docs/ecosystem/bibliography.html">bibliography</a>: arrows and categorical semantics, graded and quantitative type theory, modal type theory, dependent and inductive types, cubical type theory and univalence, and effects and handlers.</p>`,52)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};